mapper.insert:
INSERT INTO T_CORNER_TIME_INFO (
      PROVIDER_CD
    , INOUT_DAY
    , INOUT_TIME
    , INOUT_LOT
    , TERM_GROUP_ID
    , TERM_ID
    , BUSINESS_LOT
    , CARD_NUM
    , ATMS_RECEIVE_DATE
    , ATMS_RECEIVE_TIME
) VALUES (
      #{providerCd}
    , #{inoutDate}
    , #{inoutTime}
    , #{inoutType}
    , #{termGroupId}
    , #{termId}
    , #{workType}
    , #{cardNo}
    , TO_CHAR(SYSDATE, 'YYYYMMDD')
    , TO_CHAR(SYSDATE, 'HH24MISS')
)

mapper.update:
UPDATE T_CORNER
   SET GUARD_STATUS = #{inoutType}
 WHERE TERM_GROUP_ID = #{termGroupId}
   AND CORNER_CD     = (SELECT CORNER_CD
                          FROM T_ATM
                         WHERE TERM_GROUP_ID = #{termGroupId}
                           AND TERM_ID       = #{termId})

UPDATE T_FAULT_MANAGEMENT
   SET SECURITY_OFF_DATE = #{inoutDate}
     , SECURITY_OFF_TIME = #{inoutTime}
     , UPD_DT            = CURRENT_TIMESTAMP
 WHERE TERM_GROUP_ID = #{termGroupId}
   AND TERM_ID IN (SELECT B.TERM_ID
                     FROM T_ATM A, T_ATM B
                    WHERE A.TERM_GROUP_ID    = #{termGroupId}
                      AND A.TERM_ID          = #{termId}
                      AND B.TERM_GROUP_ID    = A.TERM_GROUP_ID
                      AND B.LOCATION_TYPE_CD = A.LOCATION_TYPE_CD)
   AND FAULT_STATUS IN ('O', 'P')
   AND ARRIVAL_DATE IS NULL
   AND SECURITY_OFF_DATE IS NULL
